using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Threading.Tasks;using System.Xml.Linq;
namespace V15Voice {public partial class MainForm {
 bool proseInput,readingLive;string proseFileHash="";FlowLayoutPanel proseTools;Label proseTiming=new Label();
 void BuildProseControls(FlowLayoutPanel parent){proseTools=new FlowLayoutPanel{AutoSize=true,Width=250,FlowDirection=FlowDirection.TopDown,WrapContents=false,Margin=new Padding(0)};parent.Controls.Add(proseTools);extraControls.Add(proseTools);AddLabel(proseTools,"ĐỌC VĂN BẢN DÀI",true);proseTiming.Width=250;proseTiming.AutoSize=true;proseTiming.MaximumSize=new Size(250,0);proseTiming.ForeColor=teal;proseTools.Controls.Add(proseTiming);BuildTextTargetControls(proseTools);
  proseTools.Controls.Add(Btn("Tạo lại đoạn đang chọn",async(s,e)=>await RegenerateProse()));proseTools.Controls.Add(Btn("Dùng bản đọc trước",(s,e)=>RestoreProseAudio()));proseTools.Controls.Add(Btn("Khóa / mở khóa đoạn",(s,e)=>LockProse()));
  AddLabel(proseTools,"TXT đọc tự nhiên hoặc căn theo đích khi bật tùy chọn. Audio gốc được lưu để dùng lại. Giới hạn bộ nhớ đĩa tạm khoảng 1 GB.",false);
  foreach(var control in new Control[]{voices,speed,punctuationMode,commaPause,stopPause,questionPause,paragraphPause,gap,breathMode}){var cb=control as ComboBox;if(cb!=null)cb.SelectedIndexChanged+=(s,e)=>{if(!busy){readingLive=false;RefreshProse();}};var num=control as NumericUpDown;if(num!=null)num.ValueChanged+=(s,e)=>{if(!busy){readingLive=false;RefreshProse();}};}
  RefreshProse();
 }
 void RefreshProse(){RefreshTextTarget();RefreshAnchorControls();RefreshQualityEnabled();if(proseTools==null)return;proseTools.Visible=proseInput;if(rhythmMeasure!=null)rhythmMeasure.Text=proseInput?"Nghe thử & ước lượng TXT":AnchoredMode?"Đo giọng · tất cả chặng":"Đo nhịp giọng · 5 khối";mode.Enabled=!busy&&!proseInput;if(proseInput){mode.SelectedIndex=1;grid.Columns[1].ReadOnly=grid.Columns[2].ReadOnly=true;grid.Columns[1].HeaderText=textTargetEnabled.Checked?"Đầu trước căn":"Bắt đầu";grid.Columns[2].HeaderText=textTargetEnabled.Checked?"Cuối trước căn":"Kết thúc";grid.Columns[5].HeaderText="Trạng thái đoạn";if(!readingLive){double words=cues.Sum(c=>c.Words),seconds=words/(2.5*(double)speed.Value);proseTiming.Text="Voice dự kiến sơ bộ:\r\n"+Scripts.Stamp(seconds*.75)+" – "+Scripts.Stamp(seconds*1.3)+"\r\n"+cues.Count+" đoạn · "+words+" từ\r\nBấm Tạo để cập nhật theo giọng thực tế.";}}else{grid.Columns[1].HeaderText="Bắt đầu";grid.Columns[2].HeaderText="Kết thúc";grid.Columns[1].ReadOnly=grid.Columns[2].ReadOnly=false;grid.Columns[5].HeaderText=AnchoredMode?"Căn chặng":"V15 / căn nhịp";}for(int i=0;i<cues.Count&&i<grid.Rows.Count;i++){grid.Rows[i].Cells[3].ReadOnly=!String.IsNullOrEmpty(cues[i].VoiceLock);if(proseInput&&!readingLive){grid.Rows[i].Cells[1].Value=grid.Rows[i].Cells[2].Value="Chưa có mốc";}}}
 void ReceiveReading(ReadingProgress r){if(IsDisposed||!IsHandleCreated)return;BeginInvoke((Action)(()=>{if(!readingLive&&proseTools.Visible)((ScrollableControl)proseTools.Parent).ScrollControlIntoView(proseTools);readingLive=true;proseTiming.Text=r.Summary;for(int i=0;i<cues.Count&&i<grid.Rows.Count;i++){var c=cues[i];grid.Rows[i].Cells[1].Value=i<r.Done?Scripts.Stamp(c.Start):"Chưa có mốc";grid.Rows[i].Cells[2].Value=i<r.Done?Scripts.Stamp(c.End):"Chưa có mốc";grid.Rows[i].Cells[5].Value=(String.IsNullOrEmpty(c.VoiceLock)?"":"🔒 ")+c.Status;}if(r.Final)SaveProseProject();}));}
 Cue SelectedProse(){if(!proseInput||cues.Count==0)throw new Exception("Mở TXT hoặc dán văn bản không có timecode trước.");return cues[grid.CurrentRow==null?0:grid.CurrentRow.Index];}
 async Task RegenerateProse(){try{ReadGrid();var c=SelectedProse();if(!String.IsNullOrEmpty(c.VoiceLock))throw new Exception("Mở khóa đoạn trước khi tạo lại.");var o=PacingOptions();o.BaseSpeed=(double)speed.Value;active=NewEngine();active.CheckFiles();active.Archive.Refresh=true;SetBusy(true);var engine=active;string work=Path.Combine(stateDir,"prose_preview.wav");var wave=await Task.Run(()=>{var w=Punctuation.Generate(engine,c.Text,o.BaseSpeed,o,work).Join();return FinishPreview(w,work,o);});c.Actual=wave.Duration;c.Status="Đã tạo lại · cần xuất WAV tổng";c.VoiceLock="";readingLive=false;lastOutput=null;openOutput.Enabled=false;Play(work);SaveProseProject();RefreshProse();status.Text="Đã tạo lại đoạn "+c.Id+". Bấm Tạo voice để ghép lại WAV tổng từ các đoạn đã lưu.";
 }catch(OperationCanceledException){status.Text="Đã dừng tạo lại đoạn.";}catch(Exception e){Error(e);}finally{if(active!=null)active.Dispose();active=null;SetBusy(false);RefreshProse();}}
 async Task MeasureProse(){try{ReadGrid();if(cues.Count==0)return;var sample=Enumerable.Range(0,Math.Min(5,cues.Count)).Select(i=>(int)Math.Round(i*(cues.Count-1.0)/Math.Max(1,Math.Min(5,cues.Count)-1))).Distinct().Select(i=>cues[i]).ToList();var o=PacingOptions();string calibrationKey=TargetKey();double selectedSpeed=(double)speed.Value;active=NewEngine();active.CheckFiles();var engine=active;SetBusy(true);string path=Path.Combine(stateDir,"prose_measure.wav");double seconds=0;int words=0;await Task.Run(()=>{var parts=new PacedSpeech();foreach(var c in sample){if(words>=160&&parts.Parts.Count>=2)break;if(engine.Cancelled)throw new OperationCanceledException();var part=Punctuation.Generate(engine,c.Text,selectedSpeed,o,path).Join();parts.Parts.Add(part);if(parts.Parts.Count>1)parts.Pauses.Add(.3);seconds+=part.Duration;words+=c.Words;}return FinishPreview(parts.Join(),path,o);});double estimate=seconds/Math.Max(1,words)*cues.Sum(c=>c.Words);targetCalibration=estimate+Math.Max(0,cues.Count-1)*(double)gap.Value;targetCalibrationKey=calibrationKey;RefreshTextTarget();readingLive=true;proseTiming.Text="Voice dự kiến sau đo thử:\r\n"+Scripts.Stamp(estimate*.88)+" – "+Scripts.Stamp(estimate*1.12+cues.Count*.3)+"\r\nĐã đo "+words+" từ bằng giọng đã chọn.\r\nCác đoạn đạt được giữ để render tiếp.";Play(path);status.Text="Đã đo và phát mẫu TXT. Thời lượng chính xác sẽ có khi xuất xong WAV.";
 }catch(OperationCanceledException){status.Text="Đã dừng đo TXT.";}catch(Exception e){Error(e);}finally{if(active!=null)active.Dispose();active=null;SetBusy(false);}}
 void RestoreProseAudio(){try{ReadGrid();var c=SelectedProse();if(!String.IsNullOrEmpty(c.VoiceLock))throw new Exception("Mở khóa đoạn trước khi dùng bản cũ.");var o=PacingOptions();using(var e=NewEngine()){var parts=LongText.Parts(c,o);if(parts.Any(t=>!e.Archive.CanRestore(e,t,(double)speed.Value)))throw new Exception("Đoạn này chưa có bản đọc trước theo thiết lập hiện tại.");foreach(string t in parts)e.Archive.Restore(e,t,(double)speed.Value);measuredSpeech.Clear();}c.Actual=0;c.Status="Đã chọn bản trước · cần xuất WAV tổng";readingLive=false;lastOutput=null;openOutput.Enabled=false;SaveProseProject();RefreshProse();status.Text="Đã phục hồi bản đọc trước. Bấm Tạo voice để xuất lại WAV tổng.";}catch(Exception e){Error(e);}}
 void LockProse(){try{ReadGrid();var c=SelectedProse();if(!String.IsNullOrEmpty(c.VoiceLock))c.VoiceLock="";else{var o=PacingOptions();o.BaseSpeed=(double)speed.Value;using(var e=NewEngine()){if(LongText.Parts(c,o).Any(t=>!e.Archive.Has(e,t,o.BaseSpeed)))throw new Exception("Tạo hoặc nghe thử đoạn trước khi khóa.");c.VoiceLock=LongText.Signature(e,o,c);}}SaveProseProject();RefreshProse();status.Text=String.IsNullOrEmpty(c.VoiceLock)?"Đã mở khóa đoạn":"Đã khóa đoạn; đổi thiết lập cần mở khóa để tạo lại.";}catch(Exception e){Error(e);}}
 void SaveProseProject(){if(!proseInput||cues.Count==0)return;try{var xml=new XElement("prose",new XAttribute("source",sourcePath??""),new XAttribute("sourceHash",proseFileHash),new XAttribute("targetEnabled",textTargetEnabled.Checked?1:0),new XAttribute("targetText",textTargetValue.Text));foreach(var c in cues)xml.Add(new XElement("cue",new XAttribute("start",c.Start),new XAttribute("end",c.End),new XAttribute("paragraph",c.ParagraphEnd?1:0),new XAttribute("voiceLock",c.VoiceLock??""),new XAttribute("actual",c.Actual),new XAttribute("status",c.Status),c.Text));StateFiles.Write(Path.Combine(stateDir,"prose_project.xml"),xml);}catch(Exception e){status.Text="Chưa lưu được bài TXT: "+e.Message;}}
 bool RestoreProseProject(){try{var xml=StateFiles.Read(Path.Combine(stateDir,"prose_project.xml"));if(xml==null)return false;string path=StateFiles.S(xml,"source");if(File.Exists(path)&&StateFiles.Hash(path)!=StateFiles.S(xml,"sourceHash")){LoadFile(path);if(proseInput&&StateFiles.I(xml,"targetEnabled")==1){try{SetTextTargetUI(TextTargetVoice.Parse(StateFiles.S(xml,"targetText")));SaveProseProject();}catch{}}return true;}var restored=xml.Elements("cue").Select(x=>new Cue{Start=StateFiles.D(x,"start"),End=StateFiles.D(x,"end"),Prose=true,ParagraphEnd=StateFiles.I(x,"paragraph")==1,VoiceLock=StateFiles.S(x,"voiceLock"),Actual=StateFiles.D(x,"actual"),Status=StateFiles.S(x,"status","Chưa tạo"),Text=x.Value}).ToList();LongText.Validate(restored);cues=restored;proseFileHash=StateFiles.S(xml,"sourceHash");sourcePath=File.Exists(path)?path:null;proseInput=true;settingTarget=true;try{textTargetEnabled.Checked=StateFiles.I(xml,"targetEnabled")==1;textTargetValue.Text=StateFiles.S(xml,"targetText");}finally{settingTarget=false;}mode.SelectedIndex=1;Populate();RefreshProse();status.Text="Đã mở bài TXT gần nhất; các đoạn đã lưu được dùng để tiếp tục.";return true;}catch{return false;}}
}}
